{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.weekly_channel_performance as with params as ( select dateadd(day, -1, current_date()) as as_of_date, date_trunc(\'month\', dateadd(day, -1, current_date())) as as_of_month, day(dateadd(day, -1, current_date())) as cutoff_day ), main AS ( SELECT _airbyte_data:\"Channel Ledger\"::STRING AS channel_ledger ,_airbyte_data:\"Entity\"::STRING AS entity ,_airbyte_data:\"Facility\"::STRING AS facility ,NULLIF(_airbyte_data:\"GRN Price Without Tax\"::STRING, \'\')::FLOAT AS grn_price_without_tax ,NULLIF(_airbyte_data:\"MRP\"::STRING, \'\')::FLOAT AS mrp ,_airbyte_data:\"Original_Created_Date\"::TIMESTAMP AS original_created_date ,TRY_TO_DATE(_airbyte_data:\"Original_Invoice_Date\"::VARCHAR, \'DD-MM-YYYY\') AS original_invoice_date ,_airbyte_data:\"Product SKU Code\"::STRING AS product_sku_code ,NULLIF(_airbyte_data:\"Quantity\"::STRING, \'\')::INTEGER AS quantity ,_airbyte_data:\"Sale Order Number\"::STRING AS sale_order_number ,NULLIF(_airbyte_data:\"Sales\"::STRING, \'\')::FLOAT AS sales ,NULLIF(_airbyte_data:\"Total\"::STRING, \'\')::FLOAT AS total FROM snitch_db.maplemonk._AIRBYTE_RAW_UC_AARYAN_GET_TALLY_GST_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Sale Order Number\"::STRING ,_airbyte_data:\"Product SKU Code\"::STRING ,_airbyte_data:\"Warehouse Name\"::STRING ,_airbyte_data:\"Original_Created_Date\"::TIMESTAMP ORDER BY _airbyte_data:\"Ingested At\"::TIMESTAMP DESC ) = 1 union all select channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, to_date(Original_Invoice_Date,\'DD-MM-YYYY\') as original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total from snitch_db.MAPLEMONK.MIS_JAN206_MAY20260502 union all SELECT GET(VARIANT_COL, \'Channel Ledger\')::STRING AS channel_ledger, GET(VARIANT_COL, \'Entity\')::STRING AS entity, GET(VARIANT_COL, \'Facility\')::STRING AS facility, GET(VARIANT_COL, \'GRN Price Without Tax\')::FLOAT AS grn_price_without_tax, GET(VARIANT_COL, \'MRP\')::FLOAT AS mrp, GET(VARIANT_COL, \'Original_Created_Date\')::TIMESTAMP AS original_created_date, TO_DATE(GET(VARIANT_COL, \'Original_Invoice_Date\')::VARCHAR, \'DD-MM-YYYY\') as original_invoice_date, GET(VARIANT_COL, \'Product SKU Code\')::STRING AS product_sku_code, GET(VARIANT_COL, \'Quantity\')::INT AS quantity, GET(VARIANT_COL, \'Sale Order Number\')::STRING AS sale_order_number, GET(VARIANT_COL, \'Sales\')::FLOAT AS sales, GET(VARIANT_COL, \'Total\')::FLOAT AS total FROM snitch_db.MAPLEMONK.mis_feb_20260504 union all select channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, to_date(Original_Invoice_Date,\'DD-MM-YYYY\') as original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total from snitch_db.MAPLEMONK.MIS_20260428 ), cost_price_map as ( select sku_group, cost_price, category from SNITCH_DB.MAPLEMONK.base_product qualify row_number() over (partition by sku_group order by cost_price desc) = 1 ), cat_mp as ( select case when left(UPPER(TRIM(SKUGROUP)),2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)),\'-\',0) else UPPER(TRIM(SKUGROUP)) end as sku_group, case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in (\'PYJAMAS\',\'Night Suit & Pyjamas\',\'Joggers & Trackpants\',\'Trackpants\',\'JOGGERS\') then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\',\'Chinos\') then \'Trousers\' else category end as category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over (partition by case when left(UPPER(TRIM(SKUGROUP)),2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)),\'-\',0) else UPPER(TRIM(SKUGROUP)) end order by case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in (\'PYJAMAS\',\'Night Suit & Pyjamas\',\'Joggers & Trackpants\',\'Trackpants\',\'JOGGERS\') then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\',\'Chinos\') then \'Trousers\' else category end asc) = 1 ), shopify_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(product_sku_code), CHARINDEX(\'-\',REVERSE(product_sku_code)) + 1, LEN(product_sku_code))))) AS sku_group, \'Shopify\' as Channel, sum(quantity)::int as quantity, sum(sales)::int as sales, sum((mrp*quantity))::int as mrp, sum(total)::int as total, sum(coalesce(try_to_number(nullif(regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\')), 0)*coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0))::int as cost_price from main where channel_ledger = \'Snitch\' and entity = \'NEW_INVOICE\' group by 1,2,3,4 ), shopify_net as ( select \"Display Order Number\" as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\',REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where \"Channel Ledger\" = \'Snitch\' group by 1,2 ), shopify as ( select a.*, case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end as return_qty, case when ifnull(b.return_qty,0) > quantity then \'false\' else \'true\' end as flag, sales * ((quantity - case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end)/quantity) as net_sales, mrp * ((quantity - case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end)/quantity) as net_mrp, total * ((quantity - case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end)/quantity) as net_total, cost_price * ((quantity - case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end)/quantity) as net_cost_price from shopify_gross a left join shopify_net b on a.order_name = b.order_name and a.sku_group = b.sku_group ), shopify_main as ( select a.date, b.category, a.Channel, sum(quantity) as quantity, sum(quantity-return_qty) as net_quantity, sum(total) as sales, sum(net_total) as net_sales, sum(mrp-total) as discount, sum(net_mrp-net_total) as net_discount, sum(a.cost_price) as cost_price, sum(net_cost_price) as net_cost_price from shopify a left join cost_price_map b on a.sku_group = b.sku_group group by 1,2,3 ), mp_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code))))) AS sku_group, case when channel_ledger in (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\') then \'MP_Ajio\' when channel_ledger in (\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\') then \'MP_Amazon\' when channel_ledger in (\'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\') then \'MP_Flipkart_PPMP\' when channel_ledger in (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') then \'MP_Myntra_PPMP\' when channel_ledger in (\'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\') then \'MP_Nykaa\' else \'others\' end as Channel, sum(quantity) as quantity, sum(case when channel_ledger in (\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\',\'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\') then total when channel_ledger in (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') and original_invoice_date >= \'2026-03-26\' then total+quantity*avg_cat_charges when channel_ledger in (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') then total when channel_ledger in (\'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\') then (total/0.8135)::INT when channel_ledger in (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\') then (total/0.68)::INT ELSE SALES END)::int AS SALES, sum(coalesce(try_to_number(nullif(regexp_replace(MRP, \'[^0-9.-]\', \'\'), \'\')), 0)*coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0)) as MRP, sum(coalesce(try_to_number(nullif(regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\')), 0)*coalesce(try_to_number(nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\')), 0) ) as cp from main a left join cost_price_map b on trim(upper(REVERSE(SUBSTRING(REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code))))) = b.sku_group left join snitch_db.maplemonk.AVG_GT_CHARGES c on b.category = c.category where channel_ledger in (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\',\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\',\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\',\'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\',\'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\') group by 1,2,3,4 ), mp_return as ( select \"Display Order Number\" as order_name, trim(upper(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\',REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where \"Channel Ledger\" in (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\',\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\',\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\',\'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\',\'FLIPKART_SAPLWH2\',\'SAPL_EMIZA_FLIPKART\',\'SAPL_FLIPKART\',\'FLIPKART_TAURU\') group by 1,2 ), mp_main_pre as ( select a.*, case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end as return_qty, case when ifnull(b.return_qty,0) > quantity then \'false\' else \'true\' end as flag, sales * ((quantity - case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end)/quantity) as net_sales, mrp * ((quantity - case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end)/quantity) as net_mrp, cp * ((quantity - case when ifnull(b.return_qty,0) > quantity then quantity else ifnull(b.return_qty,0) end)/quantity) as net_cp from mp_gross a left join mp_return b on a.order_name = b.order_name and a.sku_group = b.sku_group ), mp_cat as ( select upper(trim(LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))))) AS sku_group, category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over (partition by upper(trim(LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))))) order by category desc) = 1 ), mp_main as ( select a.date, coalesce(b.category,c.category) as category, a.Channel, sum(quantity) as quantity, sum(quantity-return_qty) as net_quantity, sum(sales) as sales, sum(net_sales) as net_sales, sum(mrp-sales) as discount, sum(net_mrp-net_sales) as net_discount, sum(cp) as cost_price, sum(net_cp) as net_cost_price from mp_main_pre a left join cost_price_map b on a.sku_group = b.sku_group left join mp_cat c on a.sku_group = c.sku_group group by 1,2,3 ), offline_pre as ( select b.order_date::date as date, coalesce(cp.category, \'others\') as category, \'Store\' as channel, case when marketplace_mapped in (\'SNITCH - WH - B2B\',\'SNITCH - SNITCH X\',\'SNITCH - WH - M P\',\'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - U.P\',\'SNITCH - WH - NORTH\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA\' ,\'SNITCH - WH - EMIZA\',\'SNITCH - WH - YELHANKA 2\') or b.sku_group like \'cb%\' or doc_prefix in (\'OMS\',\'QCOM\') then 1 else 0 end as filters, sum(b.shipping_quantity)::int as quantity, sum(b.shipping_quantity)::int as net_quantity, sum(b.selling_price)::int as sales, sum(b.selling_price)::int as net_sales, sum(discount)::int as discount, sum(discount)::int as net_discount, (sum(cp.cost_price * b.shipping_quantity))::int as cost_price, (sum(cp.cost_price * b.shipping_quantity))::int as net_cost_price, from snitch_db.maplemonk.store_fact_items_offline b left join cost_price_map cp on b.sku_group = cp.sku_group where coalesce(cp.category,\'others\') <> \'others\' group by 1,2,3,4 ), offline_main as ( select date, category, channel, quantity, net_quantity, sales, net_sales, discount, net_discount, cost_price, net_cost_price from offline_pre where filters = 0 ), myntra_sor as ( select TRY_TO_DATE(NULLIF(TRIM(a.order_created_date::VARCHAR), \'\'), \'YYYYMMDD\') AS date, coalesce(b.category,c.category) as category, \'MP_myntra_SOR\' as channel, sum(try_to_number(replace(a.sales::varchar,\',\',\'\'))) as quantity, sum(try_to_number(replace(a.sales::varchar,\',\',\'\'))) as net_quantity, sum(try_to_number(replace(a.revenue::varchar,\',\',\'\'))) as sales, sum(try_to_number(replace(a.revenue::varchar,\',\',\'\'))) as net_sales, sum(try_to_number(replace(a.\"MRP Sales\"::varchar,\',\',\'\')) - try_to_number(replace(a.revenue::varchar,\',\',\'\'))) as discount, sum(try_to_number(replace(a.\"MRP Sales\"::varchar,\',\',\'\')) - try_to_number(replace(a.revenue::varchar,\',\',\'\'))) as net_discount, sum(try_to_number(replace(a.cogs_qty::varchar,\',\',\'\'))) as cost_price, sum(try_to_number(replace(a.cogs_qty::varchar,\',\',\'\'))) as net_cost_price from snitch_db.maplemonk.S3_MYNTRA_B2B_GP a left join cat_mp b on upper(trim(a.style)) = b.sku_group left join mp_cat c on upper(trim(a.style)) = c.sku_group where TRY_TO_DATE(NULLIF(TRIM(a.order_created_date::VARCHAR), \'\'), \'YYYYMMDD\') is not null group by 1,2,3 ), flipkart_sor as ( select TRY_TO_DATE(NULLIF(TRIM(a.order_date_key::VARCHAR), \'\'), \'YYYYMMDD\') AS date, coalesce(b.category,c.category) as category, \'MP_flipkart_SOR\' as channel, sum(try_to_number(replace(a.units::varchar,\',\',\'\'))) as quantity, sum(try_to_number(replace(a.units::varchar,\',\',\'\'))) as net_quantity, sum(try_to_number(replace(a.SP_Qty::varchar,\',\',\'\'))) as sales, sum(try_to_number(replace(a.SP_Qty::varchar,\',\',\'\'))) as net_sales, sum(try_to_number(replace(a.\"MRP Rev\"::varchar,\',\',\'\')) - try_to_number(replace(a.SP_QTY_EXCL_GST::varchar,\',\',\'\'))) as discount, sum(try_to_number(replace(a.\"MRP Rev\"::varchar,\',\',\'\')) - try_to_number(replace(a.SP_QTY_EXCL_GST::varchar,\',\',\'\'))) as net_discount, sum(try_to_number(replace(a.COGS_UNITS::varchar,\',\',\'\'))) as cost_price, sum(try_to_number(replace(a.COGS_UNITS::varchar,\',\',\'\'))) as net_cost_price from snitch_db.maplemonk.S3_Flipkart_B2B_GP a left join cat_mp b on upper(trim(a.STYLE)) = b.sku_group left join mp_cat c on upper(trim(a.STYLE)) = c.sku_group where TRY_TO_DATE(NULLIF(TRIM(a.order_date_key::VARCHAR), \'\'), \'YYYYMMDD\') is not null group by 1,2,3 ), slikk as ( select coalesce( TRY_TO_DATE(NULLIF(TRIM(a.order_date::VARCHAR), \'\'), \'DD-MM-YYYY\'), TRY_TO_DATE(NULLIF(TRIM(a.order_date::VARCHAR), \'\'), \'DD/MM/YYYY\'), TRY_TO_DATE(NULLIF(TRIM(a.order_date::VARCHAR), \'\'), \'YYYY-MM-DD\') ) AS date, coalesce(b.category,c.category) as category, \'MP_slikk\' as channel, sum(try_to_number(a.total_quantity::varchar)) as quantity, sum(try_to_number(a.total_quantity::varchar)) as net_quantity, sum(try_to_number(replace(a.total_amount::varchar,\',\',\'\'))) as sales, sum(try_to_number(replace(a.total_amount::varchar,\',\',\'\'))) as net_sales, sum(try_to_number(replace(a.mrp::varchar,\',\',\'\')) * try_to_number(a.total_quantity::varchar) - try_to_number(replace(a.total_amount::varchar,\',\',\'\'))) as discount, sum(try_to_number(replace(a.mrp::varchar,\',\',\'\')) * try_to_number(a.total_quantity::varchar) - try_to_number(replace(a.total_amount::varchar,\',\',\'\'))) as net_discount, sum(try_to_number(replace(a.\"COGSxQty \"::varchar,\',\',\'\'))) as cost_price, sum(try_to_number(replace(a.\"COGSxQty \"::varchar,\',\',\'\'))) as net_cost_price from snitch_db.maplemonk.google_sheets_slikk a left join cat_mp b on upper(trim(a.\"Style \")) = b.sku_group left join mp_cat c on upper(trim(a.\"Style \")) = c.sku_group where coalesce( TRY_TO_DATE(NULLIF(TRIM(a.order_date::VARCHAR), \'\'), \'DD-MM-YYYY\'), TRY_TO_DATE(NULLIF(TRIM(a.order_date::VARCHAR), \'\'), \'DD/MM/YYYY\'), TRY_TO_DATE(NULLIF(TRIM(a.order_date::VARCHAR), \'\'), \'YYYY-MM-DD\') ) is not null group by 1,2,3 ), base as ( select * from shopify_main union all select * from offline_main union all select * from mp_main union all select * from myntra_sor union all select * from flipkart_sor union all select * from slikk ), base_filtered as ( select b.* from base b join params p on 1=1 where b.date <= p.as_of_date ), daily as ( select date, category, channel, sum(quantity)::number as quantity, sum(sales)::number as sales, sum(discount)::number as discount, sum(cost_price)::number as cost_price, sum(net_quantity)::number as net_quantity, sum(net_sales)::number as net_sales, sum(net_discount)::number as net_discount, sum(net_cost_price)::number as net_cost_price from base_filtered group by 1,2,3 ), daily_final as ( select d.date, d.category, d.channel, d.sales, d.quantity, d.discount, d.cost_price, d.net_sales, d.net_quantity, d.net_discount, d.net_cost_price, lag(d.sales) over (partition by d.category, d.channel order by d.date) as prev_day_sales, case when lag(d.sales) over (partition by d.category, d.channel order by d.date) = 0 then null else (d.sales - lag(d.sales) over (partition by d.category, d.channel order by d.date)) / lag(d.sales) over (partition by d.category, d.channel order by d.date) end as dod_growth from daily d ), monthly_full as ( select date_trunc(\'month\', date) as month_start, category, channel, sum(sales)::number as sales_full from daily group by 1,2,3 ), monthly_mtd_limited as ( select date_trunc(\'month\', d.date) as month_start, d.category, d.channel, sum(d.sales)::number as sales_mtd from daily d join params p on 1=1 where day(d.date) <= p.cutoff_day and date_trunc(\'month\', d.date) in ( p.as_of_month, dateadd(month, -1, p.as_of_month), dateadd(year, -1, p.as_of_month) ) group by 1,2,3 ), month_cat_channel as ( select month_start, category, channel from monthly_full union select month_start, category, channel from monthly_mtd_limited ), cur_monthly as ( select u.month_start, u.category, u.channel, coalesce(f.sales_full, 0) as sales_full, coalesce(m.sales_mtd, 0) as sales_mtd from month_cat_channel u left join monthly_full f on u.month_start = f.month_start and u.category = f.category and u.channel = f.channel left join monthly_mtd_limited m on u.month_start = m.month_start and u.category = m.category and u.channel = m.channel ), monthly_growth as ( select c.month_start, c.category, c.channel, case when c.month_start = p.as_of_month then c.sales_mtd else c.sales_full end as month_sales, case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end as prev_month_sales, case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end as prev_year_sales, case when ( case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end ) = 0 then null else ( (case when c.month_start = p.as_of_month then c.sales_mtd else c.sales_full end) - (case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end) ) / (case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end) end as mom_growth, case when ( case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end ) = 0 then null else ( (case when c.month_start = p.as_of_month then c.sales_mtd else c.sales_full end) - (case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end) ) / (case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end) end as yoy_growth from cur_monthly c join params p on 1=1 left join cur_monthly pm on pm.month_start = dateadd(month, -1, c.month_start) and pm.category = c.category and pm.channel = c.channel left join cur_monthly py on py.month_start = dateadd(year, -1, c.month_start) and py.category = c.category and py.channel = c.channel ) select d.date, date_trunc(\'month\', d.date) as month_start, d.category, d.channel, d.sales, d.quantity, d.discount, d.cost_price, d.net_sales, d.net_quantity, d.net_discount, d.net_cost_price, d.prev_day_sales, d.dod_growth, mg.month_sales, mg.prev_month_sales, mg.prev_year_sales, mg.mom_growth, mg.yoy_growth from daily_final d left join monthly_growth mg on mg.month_start = date_trunc(\'month\', d.date) and mg.category = d.category and mg.channel = d.channel order by d.date, d.category, d.channel ;",
                    "transaction": true
                }
            ) }}
